<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Conway's Game of Life</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #0a0a0f;
    color: #e0e0e0;
    font-family: 'Segoe UI', system-ui, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    overflow: hidden;
  }
  h1 {
    font-size: 1.6rem;
    margin-bottom: 12px;
    background: linear-gradient(90deg, #00ffaa, #00aaff, #aa00ff);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    letter-spacing: 2px;
  }
  #controls {
    display: flex;
    gap: 10px;
    margin-bottom: 14px;
    flex-wrap: wrap;
    justify-content: center;
  }
  button {
    padding: 8px 18px;
    border: none;
    border-radius: 20px;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    text-transform: uppercase;
    letter-spacing: 1px;
  }
  button:hover { transform: scale(1.05); }
  button:active { transform: scale(0.97); }
  #step {
    background: linear-gradient(135deg, #00cc88, #00aa66);
    color: #001a0d;
  }
  #play {
    background: linear-gradient(135deg, #0088ff, #0055cc);
    color: #fff;
  }
  #play.running {
    background: linear-gradient(135deg, #ff4444, #cc2222);
  }
  #random {
    background: linear-gradient(135deg, #aa44ff, #7700cc);
    color: #fff;
  }
  #clear {
    background: linear-gradient(135deg, #ff8800, #cc5500);
    color: #1a0d00;
  }
  #life {
    border: 2px solid #1a1a2e;
    border-radius: 4px;
    cursor: crosshair;
    box-shadow: 0 0 30px rgba(0, 170, 255, 0.15), 0 0 60px rgba(0, 255, 170, 0.05);
  }
  #info {
    margin-top: 10px;
    font-size: 0.8rem;
    color: #555;
  }
</style>
</head>
<body>
<h1>Game of Life</h1>
<div id="controls">
  <button id="step">Step</button>
  <button id="play">Play</button>
  <button id="random">Random</button>
  <button id="clear">Clear</button>
</div>
<canvas id="life" width="500" height="500"></canvas>
<div id="info">Click or drag to paint cells</div>
<script>
(function() {
  const canvas = document.getElementById('life');
  const ctx = canvas.getContext('2d');
  const COLS = 50;
  const ROWS = 50;
  const CELL = 10;

  let grid = new Uint8Array(COLS * ROWS);
  let nextGrid = new Uint8Array(COLS * ROWS);
  let running = false;
  let animId = null;
  let lastTime = 0;
  const INTERVAL = 120;

  function idx(x, y) { return y * COLS + x; }

  function get(x, y) {
    if (x < 0 || x >= COLS || y < 0 || y >= ROWS) return 0;
    return grid[idx(x, y)];
  }

  function set(x, y, v) {
    if (x < 0 || x >= COLS || y < 0 || y >= ROWS) return;
    grid[idx(x, y)] = v ? 1 : 0;
  }

  function countNeighbors(x, y) {
    let count = 0;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        count += get(x + dx, y + dy);
      }
    }
    return count;
  }

  function step() {
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        const n = countNeighbors(x, y);
        const alive = grid[idx(x, y)];
        if (alive) {
          nextGrid[idx(x, y)] = (n === 2 || n === 3) ? 1 : 0;
        } else {
          nextGrid[idx(x, y)] = (n === 3) ? 1 : 0;
        }
      }
    }
    const tmp = grid;
    grid = nextGrid;
    nextGrid = tmp;
    draw();
  }

  function clear() {
    grid.fill(0);
    draw();
  }

  function randomize() {
    for (let i = 0; i < grid.length; i++) {
      grid[i] = Math.random() < 0.3 ? 1 : 0;
    }
    draw();
  }

  function draw() {
    ctx.fillStyle = '#0d0d14';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw grid lines subtly
    ctx.strokeStyle = '#151520';
    ctx.lineWidth = 0.5;
    for (let x = 0; x <= COLS; x++) {
      ctx.beginPath();
      ctx.moveTo(x * CELL, 0);
      ctx.lineTo(x * CELL, ROWS * CELL);
      ctx.stroke();
    }
    for (let y = 0; y <= ROWS; y++) {
      ctx.beginPath();
      ctx.moveTo(0, y * CELL);
      ctx.lineTo(COLS * CELL, y * CELL);
      ctx.stroke();
    }

    // Draw alive cells
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        if (grid[idx(x, y)]) {
          const n = countNeighbors(x, y);
          let hue;
          if (n <= 1) hue = 0;
          else if (n === 2) hue = 150;
          else hue = 200;
          ctx.fillStyle = `hsl(${hue}, 100%, 55%)`;
          ctx.fillRect(x * CELL + 1, y * CELL + 1, CELL - 2, CELL - 2);
          // glow
          ctx.fillStyle = `hsla(${hue}, 100%, 70%, 0.3)`;
          ctx.fillRect(x * CELL, y * CELL, CELL, CELL);
        }
      }
    }
  }

  // Mouse interaction
  let painting = false;
  let paintValue = 1;

  function getCellFromEvent(e) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const mx = (e.clientX - rect.left) * scaleX;
    const my = (e.clientY - rect.top) * scaleY;
    const cx = Math.floor(mx / CELL);
    const cy = Math.floor(my / CELL);
    if (cx >= 0 && cx < COLS && cy >= 0 && cy < ROWS) {
      return { x: cx, y: cy };
    }
    return null;
  }

  canvas.addEventListener('mousedown', function(e) {
    e.preventDefault();
    const cell = getCellFromEvent(e);
    if (!cell) return;
    painting = true;
    paintValue = grid[idx(cell.x, cell.y)] ? 0 : 1;
    set(cell.x, cell.y, paintValue);
    draw();
  });

  canvas.addEventListener('mousemove', function(e) {
    if (!painting) return;
    const cell = getCellFromEvent(e);
    if (!cell) return;
    set(cell.x, cell.y, paintValue);
    draw();
  });

  window.addEventListener('mouseup', function() {
    painting = false;
  });

  // Touch support
  canvas.addEventListener('touchstart', function(e) {
    e.preventDefault();
    const touch = e.touches[0];
    const cell = getCellFromEvent(touch);
    if (!cell) return;
    painting = true;
    paintValue = grid[idx(cell.x, cell.y)] ? 0 : 1;
    set(cell.x, cell.y, paintValue);
    draw();
  }, { passive: false });

  canvas.addEventListener('touchmove', function(e) {
    e.preventDefault();
    if (!painting) return;
    const touch = e.touches[0];
    const cell = getCellFromEvent(touch);
    if (!cell) return;
    set(cell.x, cell.y, paintValue);
    draw();
  }, { passive: false });

  canvas.addEventListener('touchend', function() {
    painting = false;
  });

  // Button handlers
  document.getElementById('step').addEventListener('click', function() {
    step();
  });

  const playBtn = document.getElementById('play');
  playBtn.addEventListener('click', function() {
    running = !running;
    if (running) {
      playBtn.textContent = 'Pause';
      playBtn.classList.add('running');
      lastTime = performance.now();
      animId = requestAnimationFrame(loop);
    } else {
      playBtn.textContent = 'Play';
      playBtn.classList.remove('running');
      if (animId) cancelAnimationFrame(animId);
    }
  });

  document.getElementById('random').addEventListener('click', function() {
    randomize();
  });

  document.getElementById('clear').addEventListener('click', function() {
    clear();
  });

  function loop(time) {
    if (!running) return;
    if (time - lastTime >= INTERVAL) {
      step();
      lastTime = time;
    }
    animId = requestAnimationFrame(loop);
  }

  // Expose API
  window.life = {
    w: COLS,
    h: ROWS,
    get: get,
    set: set,
    step: step,
    clear: clear
  };

  // Initial draw
  draw();
})();
</script>
</body>
</html>
